,{"slug":"vllm","name":"vLLM","tagline":"High-throughput LLM serving engine — the production standard for GPU inference at scale.","description":"vLLM is a high-throughput serving engine for LLMs that uses PagedAttention for efficient memory management. It delivers 2-4x higher throughput than naive serving and is the go-to choice for production deployments on GPU clusters. Used by major AI companies for inference at scale.","website_url":"https://vllm.ai","category_slug":"local-open-source","pricing_model":"open_source","pricing_details":"Free and open-source. Apache 2.0 license.","editor_rating":4.3,"is_verified":true,"is_featured":false,"status":"published","published_at":"2026-02-13T02:32:12.296154+00:00","company_name":"vLLM","founded_year":2023,"headquarters":null,"logo_url":null,"affiliate_url":null,"meta_title":"vLLM Review, Pricing, Alternatives | AiCensus","meta_description":"vLLM is a high-throughput serving engine for LLMs that uses PagedAttention for efficient memory management. It delivers 2-4x higher throughput than naive s","key_features":["PagedAttention for efficient memory","2-4x throughput improvement","OpenAI-compatible API server","Continuous batching for concurrency","Supports most popular model architectures"],"pros":["Industry-standard for production serving","Dramatically higher throughput","Active development and community"],"cons":["Requires GPU infrastructure","Complex setup for multi-GPU","Not ideal for single-user local use"],"use_cases":["Production LLM serving","High-concurrency AI APIs","Model serving infrastructure","Batch inference pipelines"],"who_its_for":["ML infrastructure engineers","AI companies","DevOps teams","Cloud platform builders"]}
,{"slug":"wolfram-alpha","name":"Wolfram Alpha","tagline":"Computational knowledge engine — the gold standard for math, science, and data answers.","description":"Wolfram Alpha is a computational knowledge engine that answers factual queries by computing answers from structured data. Unlike search engines, it computes exact answers for math, science, engineering, and data questions. The backbone of Siri's knowledge and a trusted academic tool.","website_url":"https://www.wolframalpha.com","category_slug":"ai-education","pricing_model":"freemium","pricing_details":"Free basic queries. Pro: $7.25/mo. Pro Premium: $12/mo with step-by-step.","editor_rating":4.5,"is_verified":true,"is_featured":true,"status":"published","published_at":"2026-02-13T02:32:12.296154+00:00","company_name":"Wolfram Research","founded_year":2009,"headquarters":null,"logo_url":null,"affiliate_url":null,"meta_title":"Wolfram Alpha Review, Pricing, Alternatives | AiCensus","meta_description":"Wolfram Alpha is a computational knowledge engine that answers factual queries by computing answers from structured data. Unlike search engines, it compute","key_features":["Computational answers (not search results)","Step-by-step math solutions","Data visualization and graphing","Covers math, physics, chemistry, statistics","Natural language query input"],"pros":["Provides exact computed answers","Trusted in academia","Incredible depth for STEM subjects"],"cons":["Struggles with conversational queries","Interface feels dated","Pro needed for step-by-step"],"use_cases":["Solving complex math problems","Engineering calculations","Statistical analysis","Scientific data lookups"],"who_its_for":["STEM students","Engineers","Scientists","Data analysts","Academics"]}
,{"slug":"wordtune","name":"Wordtune","tagline":"AI writing companion for rewriting, tone adjustment, and clarity improvements.","description":"Wordtune by AI21 Labs helps rewrite and refine existing text for clarity, tone, and fluency via browser extension and web editor. It focuses on improving drafts rather than generating long-form content from scratch.","website_url":"https://www.wordtune.com","category_slug":"writing-content","pricing_model":"freemium","pricing_details":"Free: 10 rewrites/day; Advanced $13.99/mo ($6.99/mo annual); Unlimited $19.99/mo ($9.99/mo annual); Teams from $15.99/user/mo; Enterprise custom.","editor_rating":4,"is_verified":true,"is_featured":false,"status":"published","published_at":"2026-02-13T02:32:12.296154+00:00","company_name":"AI21 Labs","founded_year":2020,"headquarters":null,"logo_url":null,"affiliate_url":null,"meta_title":"Wordtune Review, Pricing, Alternatives | AiCensus","meta_description":"Wordtune by AI21 Labs helps rewrite and refine existing text for clarity, tone, and fluency via browser extension and web editor. It focuses on improving d","key_features":["Real-time sentence rewriting","Tone adjustment (casual, formal)","Sentence expansion and shortening","Browser extension for any site","Wordtune Read for document summaries"],"pros":["Excellent for improving existing text","Useful browser extension","Natural-sounding rewrites"],"cons":["Limited free tier","Not a full content generator","Sometimes changes meaning"],"use_cases":["Improving email clarity","Polishing professional writing","Adjusting tone of content","Making writing more concise"],"who_its_for":["Business professionals","Non-native English writers","Email-heavy workers","Students"]}
,{"slug":"wordware","name":"Wordware","tagline":"Prompt and agent development environment for building AI workflows with context.","description":"Wordware helps builders create, test, and ship AI workflows with structured prompts, context, tools, and collaboration. Its positioning has shifted toward AI context and agent experimentation rather than a simple prompt playground.","website_url":"https://www.wordware.ai","category_slug":"mcp-skills-platforms","pricing_model":"freemium","pricing_details":"Free building is limited; paid plans add more execution, collaboration, and production capacity.","editor_rating":4,"is_verified":true,"is_featured":false,"status":"published","published_at":"2026-02-13T02:32:12.296154+00:00","company_name":"Wordware","founded_year":2024,"headquarters":null,"logo_url":null,"affiliate_url":null,"meta_title":"Wordware Review, Pricing, Alternatives | AiCensus","meta_description":"Wordware helps builders create, test, and ship AI workflows with structured prompts, context, tools, and collaboration. Its positioning has shifted toward ","key_features":["Natural language programming","AI agent creation without code","Tool and API integrations","Version control for prompts","Collaborative editing"],"pros":["Truly accessible to non-developers","Intuitive natural language approach","Good for rapid prototyping"],"cons":["Less precise than code-based tools","Complex logic can be hard to express","Younger platform with less ecosystem"],"use_cases":["Creating AI agents with plain English","Business process automation","Rapid AI prototyping","Non-technical AI development"],"who_its_for":["Non-technical founders","Business analysts","Product managers","Citizen developers"]}
,{"slug":"writer","name":"Writer","tagline":"Enterprise generative AI platform for agents, knowledge work, governance, and business workflows.","description":"Writer is an enterprise AI platform for building agents, automating workflows, governing content, and applying company knowledge to business processes. It is positioned for regulated and large organizations that need controlled AI adoption.","website_url":"https://writer.com","category_slug":"writing-content","pricing_model":"enterprise","pricing_details":"Enterprise pricing is custom, with platform features for agents, governance, models, knowledge, and workflow automation.","editor_rating":4.2,"is_verified":true,"is_featured":false,"status":"published","published_at":"2026-02-13T02:32:12.296154+00:00","company_name":"Writer","founded_year":2020,"headquarters":null,"logo_url":null,"affiliate_url":null,"meta_title":"Writer Review, Pricing, Alternatives | AiCensus","meta_description":"Writer is an enterprise AI platform for building agents, automating workflows, governing content, and applying company knowledge to business processes. It ","key_features":["Custom brand voice AI models","Style guide enforcement","Enterprise content governance","Knowledge Graph for company context","API and integrations"],"pros":["Best for enterprise brand consistency","Custom AI model training","Strong governance and compliance"],"cons":["Expensive for small teams","Setup requires brand documentation","Overkill for individuals"],"use_cases":["Enterprise content creation","Brand voice standardization","Marketing copy at scale","Internal communications"],"who_its_for":["Enterprise marketing teams","Brand managers","Large content teams","Corporate communications"]}
,{"slug":"writesonic","name":"Writesonic","tagline":"AI SEO and generative search visibility platform for content and marketing teams.","description":"Writesonic combines AI article writing, SEO audits, and GEO tools that track brand visibility in ChatGPT, Gemini, and Google AI Overviews. It is positioned for marketers optimizing both traditional search and AI answer engines.","website_url":"https://writesonic.com","category_slug":"writing-content","pricing_model":"freemium","pricing_details":"Free tier available; Starter $79–99/mo; Basic $199–249/mo; Growth $399–499/mo; Enterprise custom. Annual billing saves ~20%.","editor_rating":4,"is_verified":true,"is_featured":false,"status":"published","published_at":"2026-02-13T02:32:12.296154+00:00","company_name":"Writesonic","founded_year":2021,"headquarters":null,"logo_url":null,"affiliate_url":null,"meta_title":"Writesonic Review, Pricing, Alternatives | AiCensus","meta_description":"Writesonic combines AI article writing, SEO audits, and GEO tools that track brand visibility in ChatGPT, Gemini, and Google AI Overviews. It is positioned","key_features":["SEO-optimized content generation","Chatsonic AI chat assistant","Botsonic custom chatbot builder","Ad copy and social media content","Brand voice customization"],"pros":["Strong SEO content features","Multiple tools in one platform","Good brand voice adaptation"],"cons":["Output can be generic without editing","Pricing can add up with heavy use","Many features feel like ChatGPT wrappers"],"use_cases":["SEO blog post creation","Marketing copy generation","Ad copy writing","Social media content"],"who_its_for":["Content marketers","SEO specialists","Social media managers","Small business owners"]}
,{"slug":"you-com","name":"You.com","tagline":"AI search and assistant platform with agents, research APIs, and multi-model chat.","description":"You.com combines AI search, chat, custom agents, and developer APIs for grounding LLMs in live web data. It serves both consumers and teams building search-augmented AI workflows.","website_url":"https://you.com","category_slug":"research-search","pricing_model":"freemium","pricing_details":"Free tier with Smart Agent access; Pro $20/mo ($15/mo annual); Max $200/mo ($150/mo annual); Enterprise custom.","editor_rating":4.1,"is_verified":true,"is_featured":false,"status":"published","published_at":"2026-02-13T02:32:12.296154+00:00","company_name":"You.com","founded_year":2020,"headquarters":null,"logo_url":null,"affiliate_url":null,"meta_title":"You.com Review, Pricing, Alternatives | AiCensus","meta_description":"You.com combines AI search, chat, custom agents, and developer APIs for grounding LLMs in live web data. It serves both consumers and teams building search","key_features":["Multiple AI modes (Smart, Genius, Create)","Web search with AI synthesis","Image generation built-in","Code generation mode","Source citations"],"pros":["Versatile multi-mode interface","Good free tier","Built-in image generation"],"cons":["Less polished than Perplexity","Genius mode can be slow","Smaller user community"],"use_cases":["Web research with AI","Quick content creation","Code generation queries","Image generation on the fly"],"who_its_for":["Researchers","Content creators","Developers","Students"]}
]$tools$::jsonb) AS t(
    slug text,
    name text,
    tagline text,
    description text,
    website_url text,
    category_slug text,
    pricing_model text,
    pricing_details text,
    editor_rating numeric,
    is_verified boolean,
    is_featured boolean,
    status text,
    published_at timestamptz,
    company_name text,
    founded_year int,
    headquarters text,
    logo_url text,
    affiliate_url text,
    meta_title text,
    meta_description text,
    key_features jsonb,
    pros jsonb,
    cons jsonb,
    use_cases jsonb,
    who_its_for jsonb
  )
)
INSERT INTO public.tools (
  name,
  slug,
  tagline,
  description,
  website_url,
  category_id,
  pricing_model,
  pricing_details,
  editor_rating,
  is_verified,
  is_featured,
  status,
  published_at,
  company_name,
  founded_year,
  headquarters,
  logo_url,
  affiliate_url,
  meta_title,
  meta_description,
  key_features,
  pros,
  cons,
  use_cases,
  who_its_for
)
SELECT
  t.name,
  t.slug,
  t.tagline,
  t.description,
  t.website_url,
  c.id,
  t.pricing_model::pricing_model,
  t.pricing_details,
  t.editor_rating,
  COALESCE(t.is_verified, false),
  COALESCE(t.is_featured, false),
  COALESCE(t.status, 'published')::tool_status,
  COALESCE(t.published_at, now()),
  t.company_name,
  t.founded_year,
  t.headquarters,
  t.logo_url,
  t.affiliate_url,
  t.meta_title,
  t.meta_description,
  ARRAY(SELECT jsonb_array_elements_text(COALESCE(t.key_features, '[]'::jsonb))),
  ARRAY(SELECT jsonb_array_elements_text(COALESCE(t.pros, '[]'::jsonb))),
  ARRAY(SELECT jsonb_array_elements_text(COALESCE(t.cons, '[]'::jsonb))),
  ARRAY(SELECT jsonb_array_elements_text(COALESCE(t.use_cases, '[]'::jsonb))),
  ARRAY(SELECT jsonb_array_elements_text(COALESCE(t.who_its_for, '[]'::jsonb)))
FROM new_tools AS t
LEFT JOIN public.categories AS c ON c.slug = t.category_slug
ON CONFLICT (slug) DO NOTHING;

COMMIT;
